(()=>{const categories={person:'人物',animal:'动物',prop:'物品／道具',other:'其他特殊角色'};let dialog,previewUrl;function currentImage(c){const v=(c.externalReferences||[]).find(v=>v.id===c.activeExternalReferenceId)||c.identityPortrait||activeMulti(c)?.jobs?.portrait||selectedFront(c);return v?{...v,id:v.id||v.job_id}:null;}function applyPlan(c){const p=c.special_reference;if(!p?.enabled)return;c.specialReference=true;c.referenceCategory=p.category||'other';c.referenceLayout=p.layout||'single';c.specialImagePrompt=p.image_prompt_zh||c.specialImagePrompt||'';c.videoIdentityPrompt=p.video_identity_prompt||c.videoIdentityPrompt||'';c.referenceImagePath=p.image_path||'';}function plan(c){c.special_reference={enabled:true,category:c.referenceCategory,layout:c.referenceLayout||'single',image_path:c.referenceImagePath||'',image_prompt_zh:c.specialImagePrompt||'',video_identity_prompt:c.videoIdentityPrompt||''};}function open(existing){if(!dialog){dialog=document.createElement('dialog');dialog.id='specialReferenceDialog';dialog.style.cssText='width:min(820px,94vw);max-height:90vh;overflow:auto;background:#182331;color:#e5edf4;border:1px solid #425364;border-radius:14px;padding:24px';document.body.append(dialog);}if(previewUrl){URL.revokeObjectURL(previewUrl);previewUrl=null;}const image=existing&&currentImage(existing);dialog.innerHTML='<div class="modal-head"><h2>'+(existing?'编辑特殊角色':'添加特殊角色')+'</h2><button data-close>✕</button></div><label>名称<input data-name maxlength="100"></label><div style="display:flex;gap:14px;flex-wrap:wrap"><label>类别<select data-category>'+Object.entries(categories).map(([k,v])=>'<option value="'+k+'">'+v+'</option>').join('')+'</select></label><label>图片形式<select data-layout><option value="single">单张图片</option><option value="multi">多视图合图 · 同一个主体</option></select></label></div><label>上传图片<input data-file type="file" accept="image/png,image/jpeg,image/webp"></label><p class="subtle">最大10MB；单图和多视图都只作为同一个主体的参考。</p><img data-preview style="max-width:100%;max-height:300px;object-fit:contain" '+(image?'':'hidden')+'><label>文生图提示词<textarea data-image-prompt rows="4" placeholder="描述要生成的主体、外观、材质、构图和背景；只写静态素材，不写视频动作。"></textarea></label><label>生成视频时的身份／外观说明<textarea data-prompt rows="5" placeholder="描述需要保留的身份、颜色、材质等。多视图属于同一个主体，不生成多个主体，不继承参考图背景、排版和文字。"></textarea></label><p data-status class="subtle"></p><div style="display:flex;gap:12px;justify-content:flex-end"><button data-cancel>取消</button><button class="primary" data-confirm>确认添加</button></div>';const q=x=>dialog.querySelector('[data-'+x+']');q('name').value=existing?.name||'';q('category').value=existing?.referenceCategory||(/兔|猫|狗|动物/.test(existing?.name||'')?'animal':'other');q('layout').value=existing?.referenceLayout||image?.reference_layout||'single';q('image-prompt').value=existing?.specialImagePrompt||existing?.prompt_anchor_zh||'';q('prompt').value=existing?.videoIdentityPrompt||'';if(image)q('preview').src=image.image_url;q('confirm').textContent=existing?'确认保存':'确认添加';q('close').onclick=q('cancel').onclick=()=>dialog.close();q('file').onchange=e=>{const file=e.target.files[0];if(!file)return;if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl=URL.createObjectURL(file);q('preview').src=previewUrl;q('preview').hidden=false;};q('confirm').onclick=async()=>{const imagePrompt=q('image-prompt').value.trim();const file=q('file').files[0],name=q('name').value.trim(),prompt=q('prompt').value.trim(),category=q('category').value,layout=q('layout').value,project=data.project_id,id=String(existing?.id||existing?.character_id||'SPECIAL_'+crypto.randomUUID());try{if(!name)throw Error('请填写名称');if(!prompt)throw Error('请填写视频参考说明');if(!file&&!image)throw Error('请上传参考图片');if(file?.size>10*1024*1024)throw Error('图片不能超过10MB');if(existing&&['running','stopping'].includes(existing.oneClick?.status))throw Error('请先停止当前角色生成');q('confirm').disabled=true;q('cancel').disabled=true;q('close').disabled=true;await ensureProjectSaved();let asset=image;if(file){q('status').textContent='正在保存参考图…';const encoded=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});asset=await frontFetch('/api/character-reference-upload',{project_id:project,character_id:id,name,new_reference:!existing,image:encoded,layout});}if(project!==data.project_id)throw Error('项目已切换，请回到原项目再确认');const c=existing||{id,character_id:id,name,role:'特殊角色',description:prompt,prompt:'',multiPrompt:'',versions:[],multi:[],portraitVersions:[]};Object.assign(c,{name,specialReference:true,referenceCategory:category,referenceLayout:layout,specialImagePrompt:imagePrompt,videoIdentityPrompt:prompt,useExternalReference:true,confirmed:true});c.externalReferences??=[];if(!c.externalReferences.some(v=>v.id===asset.id))c.externalReferences.push({...asset,reference_layout:layout});c.activeExternalReferenceId=asset.id;plan(c);if(!existing)data.characters.push(c);ci=data.characters.indexOf(c);save();await ensureProjectSaved();dialog.close();render();toast('特殊角色已保存，可在分镜中直接选择');}catch(e){q('status').textContent=e.message;}finally{q('confirm').disabled=false;q('cancel').disabled=false;q('close').disabled=false;}};dialog.showModal();}
function draw(){if(tab!==0)return;for(const c of data.characters||[])applyPlan(c);const head=document.querySelector('#panel .section-head'),add=document.createElement('button');add.id='addSpecialReference';add.textContent='＋ 添加特殊角色';add.onclick=()=>open();if(head)head.append(add);else document.querySelector('#add')?.after(add);const c=data.characters[ci];if(!c)return;const entry=document.createElement('button');entry.textContent=c.specialReference?'编辑图片与说明':'设为特殊角色';entry.style.margin='10px 0';entry.onclick=()=>open(c);const list=document.querySelector('#panel .character-list');list?.after(entry);for(const item of document.querySelectorAll('[data-char]')){const entity=data.characters[Number(item.dataset.char)];if(entity?.specialReference){const small=item.querySelector('small');if(small)small.textContent=(categories[entity.referenceCategory]||'特殊角色')+' · '+(currentImage(entity)?'已添加':'待上传');}}if(!c.specialReference)return;const image=currentImage(c),art=document.querySelector('#panel .artboard');if(art){art.style.cssText='height:auto;min-height:200px;padding:18px;display:block';art.replaceChildren();if(image){const img=document.createElement('img');img.src=image.image_url;img.alt=c.name+' · 特殊参考素材';img.style.cssText='display:block;width:100%;max-height:560px;object-fit:contain';art.append(img);const size=document.createElement('p');size.textContent=(image.width||'?')+' × '+(image.height||'?')+' px';size.className='subtle';art.append(size);}else{const empty=document.createElement('p');empty.textContent='待上传参考图'+(c.referenceImagePath?' · JSON 图片路径：'+c.referenceImagePath:'');art.append(empty);}const desc=document.createElement('div');desc.style.cssText='white-space:pre-wrap;line-height:1.8;margin-top:16px;text-align:left';desc.textContent=(c.specialImagePrompt?'文生图提示词：\n'+c.specialImagePrompt+'\n\n':'')+'视频参考说明：\n'+(c.videoIdentityPrompt||'尚未填写');art.append(desc);const edit=document.createElement('button');edit.textContent='编辑图片与说明';edit.onclick=()=>open(c);art.append(edit);const card=art.closest('.card');const title=card?.querySelector('.preview-head');if(title)title.textContent=c.name+' · '+(categories[c.referenceCategory]||'特殊角色')+'参考';card?.querySelectorAll(':scope > .preview-actions,:scope > .history,:scope > .divider,:scope > .mini-label,:scope > p.subtle').forEach(el=>el.hidden=true);const editor=card?.parentElement;if(editor?.classList.contains('editor')&&editor.lastElementChild!==card)editor.lastElementChild.hidden=true;}for(const id of ['oneClickCharacter','generate','makeMulti'])document.querySelector('#'+id)?.remove();document.querySelector('#portraitCandidates')?.remove();document.querySelectorAll('#panel button').forEach(b=>{if(/继续生成全身、侧面和背面|重新选择大头像/.test(b.textContent))b.remove();});const steps=list?.parentElement.querySelector('p.subtle');if(steps)steps.textContent='上传参考图并填写视频身份说明，即可在分镜中引用；特殊角色不需要生成人物四视图。';}
const oldChoices=shotReferenceChoices;shotReferenceChoices=function(binding){const result=oldChoices(binding);if(binding.type!=='character')return result;const c=data.characters.find(c=>(c.id||c.character_id)===binding.ref_id);if(c)applyPlan(c);const extra=(c?.externalReferences||[]).map((v,i)=>({id:v.id,url:v.image_url,label:(categories[c.referenceCategory]||'素材')+' · '+(v.reference_layout==='multi'?'多视图':'单图')+' V'+(i+1)+' · '+v.width+' × '+v.height}));return{...result,items:[...result.items,...extra.filter(v=>!result.items.some(x=>x.id===v.id))],active:c?.useExternalReference!==false&&extra.some(v=>v.id===c?.activeExternalReferenceId)?c.activeExternalReferenceId:result.active};};const oldParse=FrameJSON.parse;FrameJSON.parse=function(...args){const result=oldParse.apply(this,args);for(const c of result.characters||[])applyPlan(c);return result;};const prior=characters;characters=function(){for(const c of data.characters||[])applyPlan(c);prior();draw();};const css=document.createElement('style');css.textContent='#specialReferenceDialog::backdrop{background:#0009}#specialReferenceDialog input,#specialReferenceDialog textarea{width:100%;box-sizing:border-box}';document.head.append(css);render();})();